import {escapeHTML as e,money,range,filterTrips,quoteText,card,priceTerms} from './shared.mjs';
document.documentElement.classList.add('js');
const $=s=>document.querySelector(s);
const menu=$('#menu'),nav=$('#navigation');
function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menú de navegación')}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';nav.classList.toggle('open',open);menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Cerrar menú de navegación':'Abrir menú de navegación')});
nav.addEventListener('keydown',ev=>{if(ev.key==='Escape'){closeMenu();menu.focus()}});
let dataPromise;
function loadData(retry=false){if(!dataPromise||retry)dataPromise=fetch('/data.json',{cache:'no-cache'}).then(r=>{if(!r.ok)throw Error('No se pudo cargar');return r.json()}).then(d=>{if(!Array.isArray(d.trips)||!Array.isArray(d.destinations)||!d.agency||d.trips.some(t=>!t.id||!t.start||!d.destinations.some(x=>x.id===t.destination)))throw Error('Datos inválidos');return d}).catch(err=>{dataPromise=null;throw err});return dataPromise}
const selected=new Set();let catalogData;
function updateSelection(){document.querySelectorAll('[data-compare]').forEach(el=>{el.checked=selected.has(el.dataset.compare);el.disabled=selected.size>=3&&!el.checked});$('#open-comparison').disabled=selected.size<2;$('#open-comparison').textContent=`Comparar (${selected.size})`;$('#compare-status').textContent=selected.size?`${selected.size} de 3 viajes seleccionados${selected.size<2?'. Elige otro para comparar.':'.'}`:'Elige hasta 3 viajes para comparar.'}
function renderComparison(){const list=catalogData.trips.filter(t=>selected.has(t.id));$('#comparison-content').innerHTML=`<div class="comparison-grid" style="--count:${Math.max(1,list.length)}">${list.map(t=>{const d=catalogData.destinations.find(d=>d.id===t.destination);return `<article class="comparison-item"><p class="eyebrow">${e(d.name)}</p><h3>${e(t.hotel)}</h3><dl><dt>Fechas</dt><dd>${range(t)}</dd><dt>Duración</dt><dd>${t.nights+1} días / ${t.nights} noches</dd><dt>Transporte</dt><dd>${t.transport==='air'?'Avión':'Autobús'} desde ${e(t.origin)}</dd><dt>Precio publicado</dt><dd>${money(t.price)} MXN</dd><dt>Base y ocupación</dt><dd>${priceTerms(t)}</dd><dt>Incluye</dt><dd>${t.includes.map(e).join('; ')}</dd><dt>Impuestos y exclusiones</dt><dd>Por confirmar</dd></dl><a class="button" href="/contacto/?viaje=${t.id}">Cotizar este viaje</a><button class="secondary" data-remove="${t.id}">Quitar de comparación</button></article>`}).join('')}</div>`}
$('#close-comparison').addEventListener('click',()=>$('#comparison').close());
$('#comparison-content').addEventListener('click',ev=>{const button=ev.target.closest('[data-remove]');if(!button)return;selected.delete(button.dataset.remove);updateSelection();if(!selected.size){$('#comparison').close();return}renderComparison();$('#close-comparison').focus()});
if($('#filters')){
 const form=$('#filters'),params=new URLSearchParams(location.search);
 for(const key of ['destination','month','type','budget'])if(params.has(key)&&[...form.elements[key].options].some(o=>o.value===params.get(key)))form.elements[key].value=params.get(key);
 if(['date','price'].includes(params.get('sort')))$('#sort').value=params.get('sort');
 let request=0;
 async function search(retry=false){const token=++request;const filter=Object.fromEntries(new FormData(form));filter.sort=$('#sort').value;$('#result-count').textContent='Buscando viajes…';$('#cards').setAttribute('aria-busy','true');form.querySelector('button').disabled=true;try{const data=await loadData(retry);if(token!==request)return;catalogData=data;const list=filterTrips(data.trips,filter);$('#cards').innerHTML=list.map(t=>card(t,data.destinations.find(d=>d.id===t.destination),selected.has(t.id))).join('');$('#empty').hidden=!!list.length;$('#catalog-error').hidden=true;$('#result-count').textContent=`${list.length} ${list.length===1?'viaje encontrado':'viajes encontrados'} · ${filter.sort==='price'?'De menor a mayor precio':'Por próxima salida'}`;const query=new URLSearchParams(Object.entries(filter).filter(([k,v])=>v&&!(k==='sort'&&v==='date'))).toString();history.replaceState(null,'',location.pathname+(query?'?'+query:'')+location.hash);updateSelection()}catch{if(token!==request)return;$('#catalog-error').hidden=false;$('#result-count').textContent='No se pudo actualizar la búsqueda.'}finally{if(token===request){$('#cards').removeAttribute('aria-busy');form.querySelector('button').disabled=false}}}
 form.addEventListener('submit',ev=>{ev.preventDefault();search()});$('#sort').addEventListener('change',()=>search());
 function clear(){form.reset();form.elements.destination.value='';$('#sort').value='date';search()}
 $('#clear').addEventListener('click',clear);$('#empty-clear').addEventListener('click',clear);$('#retry').addEventListener('click',()=>search(true));
 $('#cards').addEventListener('change',async ev=>{if(!ev.target.dataset.compare)return;try{catalogData=await loadData();if(ev.target.checked&&selected.size<3)selected.add(ev.target.dataset.compare);else selected.delete(ev.target.dataset.compare);updateSelection()}catch{ev.target.checked=false;$('#catalog-error').hidden=false}});
 $('#open-comparison').addEventListener('click',()=>{renderComparison();$('#comparison').showModal()});
 if(params.size)search();
}
if($('#quote-form')){
 const form=$('#quote-form');let data,lastText='';
 function summary(){if(!data)return;const t=data.trips.find(t=>t.id===$('#trip').value);$('#selected-trip').hidden=!t;if(t){const d=data.destinations.find(d=>d.id===t.destination);$('#selected-trip').innerHTML=`<strong>${e(d.name)} · ${e(t.hotel)}</strong>${range(t)}<br>${t.nights+1} días / ${t.nights} noches · ${t.transport==='air'?'Avión':'Autobús'}<br>${money(t.price)} MXN de referencia. ${priceTerms(t)}`}$('#departure').disabled=!!t;$('#departure').value=t?t.start:''}
 function children(){const count=Number($('#children').value);$('#ages-field').hidden=count<=0;$('#ages').required=count>0}
 async function init(){try{data=await loadData();const query=new URLSearchParams(location.search);const experience=data.experiences?.find(x=>x.id===query.get('experiencia'));if(experience)$('#message').value=query.get('tour')==='tampico'?'Me interesa el tour a Tampico, Río Vista Inn, 15 y 16 de septiembre de 2026. Quiero confirmar año, tarifa, disponibilidad y servicios.':'Me interesa: '+experience.name+'. Me gustaría recibir opciones, fechas, servicios incluidos y condiciones.';const id=query.get('viaje');if(id&&data.trips.some(t=>t.id===id))$('#trip').value=id;else if(id){$('#selected-trip').hidden=false;$('#selected-trip').textContent='El paquete indicado no está disponible en esta prueba. Elige otro viaje o describe tu solicitud.'}if(!id||data.trips.some(t=>t.id===id))summary()}catch{const box=$('#form-errors');box.hidden=false;box.innerHTML='No pudimos cargar los detalles. <button type="button" id="retry-form">Reintentar</button> También puedes llamar o escribir por correo.';$('#retry-form').addEventListener('click',()=>{box.hidden=true;init()})}}
 init();$('#trip').addEventListener('change',summary);$('#children').addEventListener('input',children);
 form.addEventListener('input',()=>{$('#quote-result').hidden=true;lastText=''});form.addEventListener('change',()=>{$('#quote-result').hidden=true;lastText=''});
 const fields=['name','email','adults','children','ages','departure'];fields.forEach(key=>$('#'+key).setAttribute('aria-describedby',key+'-error'));
 form.addEventListener('submit',async ev=>{ev.preventDefault();const errors=[];fields.forEach(k=>{$('#'+k).removeAttribute('aria-invalid');$('#'+k+'-error').textContent=''});const values=Object.fromEntries(new FormData(form));const add=(key,message)=>{errors.push({key,message});$('#'+key).setAttribute('aria-invalid','true');$('#'+key+'-error').textContent=message};
 if(!values.name?.trim())add('name','Escribe tu nombre.');if(!values.email?.trim()||!$('#email').validity.valid)add('email','Escribe un correo válido, como nombre@ejemplo.com.');if(!values.adults||!Number.isInteger(Number(values.adults))||Number(values.adults)<1||Number(values.adults)>50)add('adults','Indica entre 1 y 50 adultos.');if(values.children===''||!Number.isInteger(Number(values.children))||Number(values.children)<0||Number(values.children)>20)add('children','Indica entre 0 y 20 menores.');if(Number(values.children)>0){const ages=(values.ages||'').split(',').map(s=>s.trim());if(ages.length!==Number(values.children)||ages.some(a=>a===''||!/^\d+$/.test(a)||Number(a)>17))add('ages','Escribe una edad de 0 a 17 por cada menor, separadas por comas.')}else values.ages='';
 if(values.departure&&values.departure<new Date().toISOString().slice(0,10))add('departure','Elige una fecha de hoy en adelante.');
 const box=$('#form-errors');box.hidden=!errors.length;if(errors.length){box.innerHTML='<strong>Revisa los siguientes datos:</strong><ul>'+errors.map(x=>`<li><a href="#${x.key}">${x.message}</a></li>`).join('')+'</ul>';box.focus();return}
 try{data=await loadData();const t=data.trips.find(t=>t.id===values.trip);lastText=quoteText(t,t?data.destinations.find(d=>d.id===t.destination):null,values);$('#quote-preview').textContent=lastText;$('#send-wa').href=`https://wa.me/${data.agency.whatsapp}?text=${encodeURIComponent(lastText)}`;$('#send-email').href=`mailto:${data.agency.email}?subject=${encodeURIComponent('Solicitud de cotización — '+(t?t.hotel:'Viaje a medida'))}&body=${encodeURIComponent(lastText)}`;$('#quote-result').hidden=false;$('#quote-result').focus()}catch{box.hidden=false;box.textContent='No pudimos preparar la solicitud. Reintenta con el botón Preparar mi solicitud o usa los enlaces de teléfono y correo.';box.focus()}});
 $('#download').addEventListener('click',()=>{if(!lastText)return;const url=URL.createObjectURL(new Blob([lastText],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='solicitud-cieloazul.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
}
